HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no\">\n<title>Pico HID Control</title>\n<style>\n  :root{--bg:#1a1a2e;--panel:#16213e;--edge:#2a2a4a;--fg:#e0e0e0;--dim:#8a8aa0;--accent:#0ff;--warn:#ff6b6b}\n  *{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\n  body{font-family:system-ui,sans-serif;margin:0;background:var(--bg);color:var(--fg);\n       max-width:520px;margin:0 auto;padding:10px 12px 40px;user-select:none}\n  h2{color:var(--accent);margin:6px 0 2px;font-size:19px}\n  .conn{display:flex;gap:6px;margin:8px 0}\n  .conn input{flex:1;min-width:0;padding:7px;border:1px solid var(--edge);border-radius:6px;\n              background:var(--panel);color:var(--fg);font-size:13px}\n  #status{display:flex;align-items:center;gap:6px;padding:0 10px;border:1px solid var(--edge);\n          border-radius:6px;background:var(--panel);font-size:12px;color:var(--dim);cursor:pointer;flex:none}\n  #dot{width:10px;height:10px;border-radius:50%;background:#555;flex:none}\n  #dot.ok{background:#3ad29f}#dot.err{background:var(--warn)}\n  .tabs{display:flex;gap:6px;margin:10px 0}\n  .tabs button{flex:1;padding:9px;border:1px solid var(--edge);border-radius:6px;background:var(--panel);\n               color:var(--dim);font-size:14px;font-weight:600}\n  .tabs button.on{background:var(--accent);color:var(--bg);border-color:var(--accent)}\n  .page{display:none}.page.on{display:block}\n  button.k{border:1px solid var(--edge);border-radius:10px;background:var(--panel);color:var(--fg);\n           font-size:16px;font-weight:600;padding:0;height:52px;transition:background .05s}\n  button.kk{border:1px solid var(--edge);border-radius:6px;background:var(--panel);color:var(--fg);\n            font-size:14px;font-weight:600;padding:0;height:40px;transition:background .05s}\n  button.kk:active,button.kk.press{background:var(--accent);color:var(--bg)}\n  .krow{display:grid;gap:5px;margin-top:5px}\n  .krow.r10{grid-template-columns:repeat(10,1fr)}\n  .krow.r9{grid-template-columns:repeat(9,1fr)}\n  .krow.r7{grid-template-columns:repeat(7,1fr)}\n  .wide{grid-column:span 2}\n  button.kk.lock{background:var(--accent);color:var(--bg);border-color:var(--accent)}\n  button.step.on{background:var(--accent);color:var(--bg);border-color:var(--accent)}\n  .sticks{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:10px;text-align:center}\n  .stick{position:relative;width:100%;max-width:160px;aspect-ratio:1;border-radius:50%;\n         background:var(--panel);border:1px solid var(--edge);margin:6px auto 0;touch-action:none;\n         box-shadow:inset 0 0 0 1px #0d1b33}\n  .knob{position:absolute;left:50%;top:50%;width:38%;height:38%;border-radius:50%;\n        background:var(--accent);transform:translate(-50%,-50%);pointer-events:none;transition:transform .04s}\n  .stick.hold .knob{transition:none}\n  .sval{font-family:monospace;font-size:12px;color:var(--dim);margin-top:6px}\n  button.k:active,button.k.press{background:var(--accent);color:var(--bg)}\n  .grid{display:grid;gap:8px;margin-top:10px}\n  .lbl{color:var(--dim);font-size:12px;margin:14px 0 4px;text-transform:uppercase;letter-spacing:.05em}\n  /* gamepad layout */\n  .pad{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:8px}\n  .dpad{display:grid;grid-template-columns:repeat(3,1fr);grid-template-rows:repeat(3,1fr);gap:6px;aspect-ratio:1}\n  .dpad .sp{visibility:hidden}\n  .face{display:grid;grid-template-columns:repeat(3,1fr);grid-template-rows:repeat(3,1fr);gap:6px;aspect-ratio:1}\n  .row3{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:10px}\n  .row4{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:8px}\n  .row2{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px}\n  textarea,input.txt{width:100%;padding:9px;border:1px solid var(--edge);border-radius:6px;\n                     background:var(--panel);color:var(--fg);font-size:15px}\n  #log{margin-top:12px;font-family:monospace;font-size:12px;color:var(--dim);min-height:16px;\n       white-space:pre-wrap;word-break:break-all}\n  small{color:var(--dim);font-size:11px}\n</style>\n</head>\n<body>\n<h2>Pico HID Control</h2>\n<div class=\"conn\">\n  <input id=\"ip\" placeholder=\"192.168.x.x\" autocomplete=\"off\" autocapitalize=\"off\" spellcheck=\"false\">\n  <input id=\"tok\" type=\"text\" placeholder=\"token\" autocomplete=\"off\" autocapitalize=\"off\" spellcheck=\"false\">\n  <span id=\"status\" title=\"tap to re-test\"><span id=\"dot\"></span><span id=\"stxt\">test</span></span>\n</div>\n\n<div class=\"tabs\">\n  <button data-p=\"gp\" class=\"on\">Gamepad</button>\n  <button data-p=\"kb\">Keyboard</button>\n  <button data-p=\"ms\">Mouse</button>\n</div>\n\n<!-- GAMEPAD -->\n<div class=\"page on\" id=\"gp\">\n  <div class=\"lbl\">Sticks \u2014 drag to push, release to centre</div>\n  <div class=\"sticks\">\n    <div>\n      <div class=\"stick\" data-side=\"left\"><div class=\"knob\"></div></div>\n      <div class=\"sval\" id=\"svleft\">L \u00b7 0, 0</div>\n    </div>\n    <div>\n      <div class=\"stick\" data-side=\"right\"><div class=\"knob\"></div></div>\n      <div class=\"sval\" id=\"svright\">R \u00b7 0, 0</div>\n    </div>\n  </div>\n  <div class=\"pad\">\n    <div>\n      <div class=\"lbl\">D-pad</div>\n      <div class=\"dpad\">\n        <span class=\"sp\"></span><button class=\"k\" data-dpad=\"up\">\u25b2</button><span class=\"sp\"></span>\n        <button class=\"k\" data-dpad=\"left\">\u25c0</button><button class=\"k\" data-dpad=\"neutral\">\u2022</button><button class=\"k\" data-dpad=\"right\">\u25b6</button>\n        <span class=\"sp\"></span><button class=\"k\" data-dpad=\"down\">\u25bc</button><span class=\"sp\"></span>\n      </div>\n    </div>\n    <div>\n      <div class=\"lbl\">Buttons</div>\n      <div class=\"face\">\n        <span class=\"sp\"></span><button class=\"k\" data-tap=\"x\">X</button><span class=\"sp\"></span>\n        <button class=\"k\" data-tap=\"y\">Y</button><span class=\"sp\"></span><button class=\"k\" data-tap=\"a\">A</button>\n        <span class=\"sp\"></span><button class=\"k\" data-tap=\"b\">B</button><span class=\"sp\"></span>\n      </div>\n    </div>\n  </div>\n  <div class=\"row4\">\n    <button class=\"k\" data-tap=\"l\">L</button><button class=\"k\" data-tap=\"r\">R</button>\n    <button class=\"k\" data-tap=\"zl\">ZL</button><button class=\"k\" data-tap=\"zr\">ZR</button>\n  </div>\n  <div class=\"row4\">\n    <button class=\"k\" data-tap=\"minus\">\u2212</button><button class=\"k\" data-tap=\"plus\">+</button>\n    <button class=\"k\" data-tap=\"home\">\u2302</button><button class=\"k\" data-tap=\"capture\">\u25c9</button>\n  </div>\n  <div class=\"row2\">\n    <button class=\"k\" data-tap=\"l+r\">L + R</button>\n    <button class=\"k\" data-hold=\"home\">Hold \u2302 (wake)</button>\n  </div>\n  <small>Tap = 130 ms press. \"Hold \u2302\" holds ~800 ms to wake the console.</small>\n</div>\n\n<!-- KEYBOARD -->\n<div class=\"page\" id=\"kb\">\n  <div class=\"row2\" style=\"margin-top:4px\">\n    <input class=\"txt\" id=\"typed\" placeholder=\"type a string, e.g. a name\" style=\"grid-column:span 1\">\n    <button class=\"k\" id=\"typeBtn\">Type</button>\n  </div>\n  <div class=\"lbl\">Full keyboard \u2014 tap a key</div>\n  <div class=\"krow r10\">\n    <button class=\"kk\" data-ktap=\"1\">1</button><button class=\"kk\" data-ktap=\"2\">2</button><button class=\"kk\" data-ktap=\"3\">3</button><button class=\"kk\" data-ktap=\"4\">4</button><button class=\"kk\" data-ktap=\"5\">5</button><button class=\"kk\" data-ktap=\"6\">6</button><button class=\"kk\" data-ktap=\"7\">7</button><button class=\"kk\" data-ktap=\"8\">8</button><button class=\"kk\" data-ktap=\"9\">9</button><button class=\"kk\" data-ktap=\"0\">0</button>\n  </div>\n  <div class=\"krow r10\">\n    <button class=\"kk\" data-ktap=\"q\">Q</button><button class=\"kk hk\" data-ktap=\"w\">W</button><button class=\"kk\" data-ktap=\"e\">E</button><button class=\"kk\" data-ktap=\"r\">R</button><button class=\"kk\" data-ktap=\"t\">T</button><button class=\"kk\" data-ktap=\"y\">Y</button><button class=\"kk\" data-ktap=\"u\">U</button><button class=\"kk\" data-ktap=\"i\">I</button><button class=\"kk\" data-ktap=\"o\">O</button><button class=\"kk\" data-ktap=\"p\">P</button>\n  </div>\n  <div class=\"krow r9\">\n    <button class=\"kk hk\" data-ktap=\"a\">A</button><button class=\"kk hk\" data-ktap=\"s\">S</button><button class=\"kk hk\" data-ktap=\"d\">D</button><button class=\"kk\" data-ktap=\"f\">F</button><button class=\"kk\" data-ktap=\"g\">G</button><button class=\"kk\" data-ktap=\"h\">H</button><button class=\"kk\" data-ktap=\"j\">J</button><button class=\"kk\" data-ktap=\"k\">K</button><button class=\"kk\" data-ktap=\"l\">L</button>\n  </div>\n  <div class=\"krow\" style=\"grid-template-columns:1.5fr repeat(7,1fr)\">\n    <button class=\"kk\" id=\"shiftToggle\">\u21e7 Shift</button><button class=\"kk\" data-ktap=\"z\">Z</button><button class=\"kk\" data-ktap=\"x\">X</button><button class=\"kk\" data-ktap=\"c\">C</button><button class=\"kk\" data-ktap=\"v\">V</button><button class=\"kk\" data-ktap=\"b\">B</button><button class=\"kk\" data-ktap=\"n\">N</button><button class=\"kk\" data-ktap=\"m\">M</button>\n  </div>\n  <div class=\"krow r10\">\n    <button class=\"kk wide\" data-ktap=\"escape\">Esc</button><button class=\"kk\" data-ktap=\"tab\">Tab</button><button class=\"kk wide\" data-ktap=\"space\">Space</button><button class=\"kk\" data-ktap=\"backspace\">\u232b</button><button class=\"kk wide\" data-ktap=\"enter\">Enter</button><button class=\"kk\" data-ktap=\"minus\">-</button><button class=\"kk\" data-ktap=\"equal\">=</button>\n  </div>\n  <div class=\"krow r10\">\n    <button class=\"kk\" data-ktap=\"up\">\u25b2</button><button class=\"kk\" data-ktap=\"down\">\u25bc</button><button class=\"kk\" data-ktap=\"left\">\u25c0</button><button class=\"kk\" data-ktap=\"right\">\u25b6</button><button class=\"kk\" data-ktap=\"comma\">,</button><button class=\"kk\" data-ktap=\"period\">.</button><button class=\"kk\" data-ktap=\"slash\">/</button><button class=\"kk\" data-ktap=\"semicolon\">;</button><button class=\"kk\" data-ktap=\"grave\">`</button><button class=\"kk\" data-ktap=\"delete\">Del</button>\n  </div>\n  <div class=\"lbl\">Hold (press-and-hold, for games)</div>\n  <div class=\"row4\">\n    <button class=\"k\" data-khold=\"w\">W</button><button class=\"k\" data-khold=\"a\">A</button><button class=\"k\" data-khold=\"s\">S</button><button class=\"k\" data-khold=\"d\">D</button>\n  </div>\n  <div class=\"row3\">\n    <button class=\"k\" data-khold=\"shift\">Shift</button><button class=\"k\" data-khold=\"space\">Space</button>\n    <button class=\"k\" data-cmd=\"key release\">Release all</button>\n  </div>\n  <small>Tap keys fire once. Tap \u21e7 Shift then a key for a capital or shifted symbol\n  (one-shot). Hold buttons stay down until released. Longer strings: use Type.</small>\n</div>\n\n<!-- MOUSE -->\n<div class=\"page\" id=\"ms\">\n  <div class=\"lbl\">Move (nudge) &nbsp;\u00b7&nbsp; step size</div>\n  <div style=\"display:grid;grid-template-columns:180px 84px;gap:12px;align-items:start\">\n    <div class=\"face\" style=\"max-width:180px\">\n      <button class=\"k\" data-move=\"-1,-1\">\u2196</button><button class=\"k\" data-move=\"0,-1\">\u25b2</button><button class=\"k\" data-move=\"1,-1\">\u2197</button>\n      <button class=\"k\" data-move=\"-1,0\">\u25c0</button><span class=\"sp\"></span><button class=\"k\" data-move=\"1,0\">\u25b6</button>\n      <button class=\"k\" data-move=\"-1,1\">\u2199</button><button class=\"k\" data-move=\"0,1\">\u25bc</button><button class=\"k\" data-move=\"1,1\">\u2198</button>\n    </div>\n    <div style=\"display:grid;grid-template-rows:repeat(4,1fr);gap:8px\">\n      <button class=\"k step\" data-step=\"20\">20</button><button class=\"k step on\" data-step=\"60\">60</button>\n      <button class=\"k step\" data-step=\"150\">150</button><button class=\"k step\" data-step=\"400\">400</button>\n    </div>\n  </div>\n  <div class=\"lbl\">Buttons</div>\n  <div class=\"row3\">\n    <button class=\"k\" data-click=\"left\">Left</button><button class=\"k\" data-click=\"middle\">Mid</button>\n    <button class=\"k\" data-click=\"right\">Right</button>\n  </div>\n  <div class=\"lbl\">Scroll</div>\n  <div class=\"row2\">\n    <button class=\"k\" data-scroll=\"3\">Up</button><button class=\"k\" data-scroll=\"-3\">Down</button>\n  </div>\n</div>\n\n<div class=\"lbl\" style=\"margin-top:16px\">Record</div>\n<div class=\"row2\">\n  <button class=\"k\" id=\"recBtn\">\u25cf Record</button>\n  <button class=\"k\" id=\"recClear\">Clear</button>\n</div>\n<textarea id=\"recOut\" rows=\"6\" spellcheck=\"false\" placeholder=\"recorded commands appear here as you tap while recording\" style=\"margin-top:8px;font-family:monospace;font-size:13px\"></textarea>\n<div class=\"row2\" style=\"margin-top:8px\">\n  <input class=\"txt\" id=\"recName\" placeholder=\"macro name\" style=\"grid-column:span 1\">\n  <button class=\"k\" id=\"recSave\">Save to device</button>\n</div>\n<div class=\"row2\" style=\"margin-top:8px\">\n  <button class=\"k\" id=\"recCopy\">Copy</button>\n  <button class=\"k\" id=\"recLoad\">Load into text</button>\n</div>\n<small>Records the commands you tap, with the pauses between them as <code>sleep</code>.\nSave writes it to the Pico as a macro (run it with <code>macro run &lt;name&gt;</code>).</small>\n\n<div id=\"log\">enter IP + token, tap the dot to test</div>\n\n<script>\nconst $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];\n// SERVED = this page came from the Pico itself (same-origin) vs opened as a\n// local file. Same-origin can read API responses; a local file cannot (no-cors).\nconst SERVED = location.protocol==='http:'||location.protocol==='https:';\nconst ip=$('#ip'), tok=$('#tok'), dot=$('#dot'), log=$('#log');\ntry{ip.value=localStorage.getItem('pico_ip')||'';tok.value=localStorage.getItem('hid_token')||'';}catch(e){}\nif(SERVED)ip.style.display='none';           // IP is implicit when served on-device\nlet pingTimer=0;\nfunction schedulerPing(){clearTimeout(pingTimer);pingTimer=setTimeout(ping,500);}\nip.oninput=()=>{try{localStorage.setItem('pico_ip',ip.value)}catch(e){};schedulerPing();};\ntok.oninput=()=>{try{localStorage.setItem('hid_token',tok.value)}catch(e){};if(SERVED)schedulerPing();};\nif(SERVED||ip.value)setTimeout(ping,300);\n\n// Served on-device (same-origin): normal fetch, read the real response.\n// Local file (cross-origin): no-cors + text/plain to dodge the CORS preflight\n// the device can't answer; response is opaque, so we watch the screen.\nasync function send(cmd){\n  log.textContent=cmd;\n  recTap(cmd);\n  const url=(SERVED?'':'http://'+ip.value)+'/api';\n  const opts={method:'POST',headers:{'Content-Type':'text/plain'},\n              body:JSON.stringify({cmd:cmd,delay:0,token:tok.value})};\n  if(!SERVED)opts.mode='no-cors';\n  try{\n    const r=await fetch(url,opts);\n    if(SERVED){\n      const j=await r.json();\n      if(!j.ok)log.textContent='ERR: '+(j.error||j.result||'failed');\n      else if(j.result&&j.result!=='OK')log.textContent=j.result;\n    }\n  }catch(e){if(SERVED)log.textContent='ERR '+e.message;}\n}\n\n// --- recorder: the page already generates every command, so recording is just\n//     capturing them with timing and emitting sleeps for the gaps. ---\nlet recording=false, recLast=0, recBody=[];\nconst recBtn=$('#recBtn'), recOut=$('#recOut');\nfunction recRender(){recOut.value=recBody.join('\\n');recOut.scrollTop=recOut.scrollHeight;}\nfunction recTap(cmd){\n  if(!recording)return;\n  if(cmd.indexOf('macro ')===0)return;   // don't record macro-management commands\n\n  const now=performance.now();\n  if(recBody.length){                       // no leading sleep before the first command\n    const ms=Math.max(0,Math.round((now-recLast)/10)*10);\n    if(ms>0)recBody.push('sleep '+ms);\n  }\n  recBody.push(cmd);\n  recLast=now;\n  recRender();\n}\nrecBtn.onclick=()=>{\n  recording=!recording;\n  recBtn.textContent=recording?'\u25a0 Stop':'\u25cf Record';\n  recBtn.classList.toggle('lock',recording);\n  if(recording)recLast=performance.now();\n};\n$('#recClear').onclick=()=>{recBody=[];recRender();};\n$('#recCopy').onclick=()=>{navigator.clipboard&&navigator.clipboard.writeText(recOut.value);log.textContent='copied';};\n$('#recLoad').onclick=()=>{$('#typed').value=recOut.value;};\n$('#recSave').onclick=()=>{\n  const n=$('#recName').value.trim();\n  if(!n){log.textContent='name required';return;}\n  const body=recOut.value.trim();\n  if(!body){log.textContent='nothing recorded';return;}\n  send('macro save '+n+'\\n'+body);          // body follows on later lines\n  log.textContent=\"saved macro '\"+n+\"' (run: macro run \"+n+\")\";\n};\nconst stxt=()=>document.querySelector('#stxt');\nasync function ping(){\n  if(!SERVED&&!ip.value){dot.className='';stxt().textContent='test';log.textContent='';return;}\n  dot.className='';stxt().textContent='\u2026';\n  try{\n    if(SERVED){                               // same-origin: really validate the token\n      const r=await fetch('/api',{method:'POST',headers:{'Content-Type':'text/plain'},\n        body:JSON.stringify({cmd:'ping',delay:0,token:tok.value})});\n      const j=await r.json();\n      if(j.ok){dot.className='ok';stxt().textContent='connected';log.textContent='connected \u00b7 token OK';}\n      else{dot.className='err';stxt().textContent='bad token';log.textContent='ERR: '+(j.error||'unauthorized');}\n    }else{\n      await fetch('http://'+ip.value+'/health',{mode:'no-cors'});\n      dot.className='ok';stxt().textContent='reachable';\n      log.textContent='reachable at '+ip.value+' (token not checked here)';\n    }\n  }catch(e){dot.className='err';stxt().textContent='no response';log.textContent='no response';}\n}\ndocument.querySelector('#status').onclick=ping;\n\n// tabs\n$$('.tabs button').forEach(b=>b.onclick=()=>{\n  $$('.tabs button').forEach(x=>x.classList.toggle('on',x===b));\n  $$('.page').forEach(p=>p.classList.toggle('on',p.id===b.dataset.p));\n});\n\n// --- gamepad ---\n$$('[data-tap]').forEach(b=>b.onclick=()=>send('pad tap '+b.dataset.tap));\n$$('[data-dpad]').forEach(b=>b.onclick=()=>send(\n  b.dataset.dpad==='neutral'?'pad dpad neutral':'pad dpad '+b.dataset.dpad));\n$$('[data-hold]').forEach(b=>b.onclick=()=>send('pad tap '+b.dataset.hold+' 800'));\n\n// --- keyboard ---\n$('#typeBtn').onclick=()=>{if($('#typed').value)send('key type '+$('#typed').value);};\nlet shift=false;\nconst shBtn=$('#shiftToggle');\nfunction setShift(v){shift=v;shBtn.classList.toggle('lock',shift);}\nshBtn.onclick=()=>setShift(!shift);\n$$('[data-ktap]').forEach(b=>b.onclick=()=>{\n  const k=b.dataset.ktap;\n  if(shift){\n    send('key mod shift '+k);   // one shifted keypress: Shift+K -> capital or symbol\n    setShift(false);            // shift is one-shot, like a real Caps tap\n  }else{\n    send('key tap '+k);\n  }\n});\n// press-and-hold for movement keys\nfunction holdBind(el, downCmd, upCmd){\n  const down=e=>{e.preventDefault();el.classList.add('press');send(downCmd);};\n  const up=e=>{e.preventDefault();el.classList.remove('press');send(upCmd);};\n  el.addEventListener('pointerdown',down);\n  el.addEventListener('pointerup',up);\n  el.addEventListener('pointerleave',e=>{if(el.classList.contains('press'))up(e);});\n  el.addEventListener('pointercancel',up);\n}\n$$('[data-khold]').forEach(b=>holdBind(b,'key down '+b.dataset.khold,'key up '+b.dataset.khold));\n$$('[data-cmd]').forEach(b=>b.onclick=()=>send(b.dataset.cmd));\n\n// --- mouse ---\nlet step=60;\n$$('.step').forEach(b=>b.onclick=()=>{step=+b.dataset.step;$$('.step').forEach(x=>x.classList.toggle('on',x===b));});\n$$('[data-move]').forEach(b=>b.onclick=()=>{\n  const [sx,sy]=b.dataset.move.split(',').map(Number);\n  send('mouse move '+(sx*step)+' '+(sy*step));\n});\n$$('[data-click]').forEach(b=>b.onclick=()=>send('mouse click '+b.dataset.click));\n$$('[data-scroll]').forEach(b=>b.onclick=()=>send('mouse scroll '+b.dataset.scroll));\n\n// --- analog sticks ---\n// Only send on meaningful change; the device streams the last value, so a held\n// stick needs no traffic. Throttle active dragging to ~10/s.\nfunction makeStick(el){\n  const side=el.dataset.side, tag=side==='left'?'L':'R';\n  const knob=el.querySelector('.knob'), sval=$('#sv'+side);\n  let active=false,last=0,lx=0,ly=0;\n  function out(px,py){                                  // px,py: pixels from centre\n    const R=el.clientWidth/2;\n    let d=Math.hypot(px,py); if(d>R){px=px/d*R;py=py/d*R;}\n    knob.style.transform=`translate(calc(-50% + ${px}px), calc(-50% + ${py}px))`;\n    const x=Math.round(px/R*100), y=Math.round(-py/R*100);   // invert Y: up = +\n    const now=performance.now();\n    if(now-last<100 && Math.abs(x-lx)<8 && Math.abs(y-ly)<8) return;\n    last=now;lx=x;ly=y;sval.textContent=tag+' \u00b7 '+x+', '+y;\n    send('pad stick '+side+' '+x+' '+y);\n  }\n  function at(e){const r=el.getBoundingClientRect();\n    out(e.clientX-r.left-r.width/2, e.clientY-r.top-r.height/2);}\n  function centre(){knob.style.transform='translate(-50%,-50%)';lx=ly=0;last=0;\n    sval.textContent=tag+' \u00b7 0, 0';send('pad stick '+side+' 0 0');}\n  el.addEventListener('pointerdown',e=>{active=true;el.classList.add('hold');\n    try{el.setPointerCapture(e.pointerId)}catch(_){}at(e);});\n  el.addEventListener('pointermove',e=>{if(active)at(e);});\n  const up=()=>{if(active){active=false;el.classList.remove('hold');centre();}};\n  el.addEventListener('pointerup',up);\n  el.addEventListener('pointercancel',up);\n  el.addEventListener('lostpointercapture',up);\n}\n$$('.stick').forEach(makeStick);\n</script>\n</body>\n</html>\n"
